    response = UserSchema(view="user", many=True).dump(users.items)

    if response.errors:
        return {"success": False, "errors": response.errors}, 400

    return {
        "meta": {
            "pagination": {
                "page": users.page,
                "next": users.next_num,
                "prev": users.prev_num,
                "pages": users.pages,
                "per_page": users.per_page,
