    Solves.query.filter_by(user_id=user_id).delete()
    Tracking.query.filter_by(user_id=user_id).delete()
    Users.query.filter_by(id=user_id).delete()
    db.session.commit()
    db.session.close()

    clear_user_session(user_id=user_id)
    clear_standings()
    clear_challenges()

    return {"success": True}

