def before_get(self, parser, section, option, value, defaults):
    value = super().before_get(parser, section, option, value, defaults)
    envvar = os.getenv(option)
    if value == "" and envvar:
        return process_string_var(envvar, key=option)
    else:
        return value

def process_string_var(value, key=None):
    if key in _FORCED_EXTRA_CONFIG_TYPES:
        t = _FORCED_EXTRA_CONFIG_TYPES[key]
        if t == "str":
            return str(value)
        elif t == "int":
            return int(value)
        elif t == "float":
            return float(value)
        elif t == "bool":
            return bool(strtobool(value))

    if value == "":
        return None

    if value.isdigit():
        return int(value)
    elif value.replace(".", "", 1).isdigit():
        return float(value)

    try:
        return bool(strtobool(value))
    except ValueError:
        return value

def process_boolean_str(value):
    if type(value) is bool:
        return value

    if value is None:
        return False

    if value == "":
        return None

    return bool(strtobool(value))

def empty_str_cast(value, default=None):
    if value == "":
        return default
    return value

def gen_secret_key():
    # Attempt to read the secret from the secret file
    # This will fail if the secret has not been written
    try:
        with open(".ctfd_secret_key", "rb") as secret:
            key = secret.read()
    except OSError:
        key = None

    if not key:
        key = os.urandom(64)
        # Attempt to write the secret file
        # This will fail if the filesystem is read-only
        try:
            with open(".ctfd_secret_key", "wb") as secret:
                secret.write(key)
                secret.flush()
        except OSError:
            pass
    return key

