def get_user_page_menu_bar():
    """
    Access the list used to store the user page menu bar

    :return: Returns a list of Menu namedtuples. They have name, and route attributes.
    """
    pages = []
    for p in get_pages() + app.plugin_menu_bar:
        if p.route.startswith("http"):
            route = p.route
        else:
            route = url_for("views.static_html", route=p.route)
        pages.append(Menu(title=p.title, route=route, link_target=p.link_target))
    return pages

def get_plugin_names():
    modules = sorted(glob.glob(app.plugins_dir + "/*"))
    blacklist = {"__pycache__"}
    plugins = []
    for module in modules:
        module_name = os.path.basename(module)
        if os.path.isdir(module) and module_name not in blacklist:
            plugins.append(module_name)
    return plugins

@classmethod
def create(cls, request):
    """
    This method is used to process the challenge creation request.

    :param request:
    :return:
    """
    data = dict(request.form or request.get_json() or {})
    if "scheduled_at" in data:
        try:
            data["scheduled_at"] = parse_iso_datetime(data["scheduled_at"])
        except ValueError:
            raise ChallengeCreateException(
                "Invalid 'scheduled_at' — expected ISO 8601 datetime"
            )

    challenge = cls.challenge_model(**data)

    if challenge.function in DECAY_FUNCTIONS:
        if data.get("value") and not data.get("initial"):
            challenge.initial = data["value"]

        for attr in ("initial", "minimum", "decay"):
            db.session.rollback()
            if getattr(challenge, attr) is None:
                raise ChallengeCreateException(
                    f"Missing '{attr}' but function is {challenge.function}"
                )

    db.session.add(challenge)
    db.session.commit()

    # If the challenge is dynamic we should calculate a new value
    if challenge.function in DECAY_FUNCTIONS:
        return calculate_value(challenge)

    return challenge

@classmethod
def update(cls, challenge, request):
    """
    This method is used to update the information associated with a challenge. This should be kept strictly to the
    Challenges table and any child tables.

    :param challenge:
    :param request:
    :return:
    """
    data = dict(request.form or request.get_json() or {})
    if "scheduled_at" in data:
        try:
            data["scheduled_at"] = parse_iso_datetime(data["scheduled_at"])
        except ValueError:
            raise ChallengeUpdateException("Invalid input for 'scheduled_at'")

    for attr, value in data.items():
        # We need to set these to floats so that the next operations don't operate on strings
        if attr in ("initial", "minimum", "decay") and value is not None:
            try:
                value = float(value)
            except (ValueError, TypeError):
                db.session.rollback()
                raise ChallengeUpdateException(f"Invalid input for '{attr}'")
        setattr(challenge, attr, value)

    for attr in ("initial", "minimum", "decay"):
        if (
            challenge.function in DECAY_FUNCTIONS
            and getattr(challenge, attr) is None
        ):
            db.session.rollback()
            raise ChallengeUpdateException(
                f"Missing '{attr}' but function is {challenge.function}"
            )

    db.session.commit()

    # If the challenge is dynamic we should calculate a new value
    if challenge.function in DECAY_FUNCTIONS:
        return calculate_value(challenge)

    # If we don't support dynamic we just don't do anything
    return challenge

@classmethod
def attempt(cls, challenge, request):
    """
    This method is used to check whether a given input is right or wrong. It does not make any changes and should
    return a boolean for correctness and a string to be shown to the user. It is also in charge of parsing the
    user's input from the request itself.

    :param challenge: The Challenge object from the database
    :param request: The request the user submitted
    :return: (boolean, string)
    """
    data = request.form or request.get_json()
    submission = data["submission"].strip()

    flags = Flags.query.filter_by(challenge_id=challenge.id).all()

    if challenge.logic == "any":
        return challenge_attempt_any(submission, challenge, flags)
    elif challenge.logic == "all":
        return challenge_attempt_all(submission, challenge, flags)
    elif challenge.logic == "team":
        return challenge_attempt_team(submission, challenge, flags)
    else:
        return challenge_attempt_any(submission, challenge, flags)

def challenge_attempt_any(submission, challenge, flags):
    from CTFd.plugins.challenges import ChallengeResponse

    for flag in flags:
        try:
            if get_flag_class(flag.type).compare(flag, submission):
                return ChallengeResponse(
                    status="correct",
                    message="Correct",
                )
        except FlagException as e:
            return ChallengeResponse(
                status="incorrect",
                message=str(e),
            )
    return ChallengeResponse(
        status="incorrect",
        message="Incorrect",
    )

def challenge_attempt_all(submission, challenge, flags):
    from CTFd.plugins.challenges import ChallengeResponse

    user = get_current_user()
    partials = Partials.query.filter_by(
        account_id=user.account_id, challenge_id=challenge.id
    ).all()
    provideds = [partial.provided for partial in partials]
    provideds.append(submission)

    target_flags_ids = {flag.id for flag in flags}
    compared_flag_ids = []

    for flag in flags:
        # Skip flags that we have already evaluated as captured
        if flag.id in compared_flag_ids:
            continue
        flag_class = get_flag_class(flag.type)
        for provided in provideds:
            if flag_class.compare(flag, provided):
                compared_flag_ids.append(flag.id)

    # If we have captured against all flag IDs the challenge is correct
    if target_flags_ids == set(compared_flag_ids):
        return ChallengeResponse(
            status="correct",
            message="Correct",
        )

    # If we didn't capture all flag IDs we must be missing something.
    for flag in flags:
        if get_flag_class(flag.type).compare(flag, submission):
            return ChallengeResponse(
                status="partial",
                message="Correct but more flags are required",
            )

    # Input is just wrong
    return ChallengeResponse(
        status="incorrect",
        message="Incorrect",
    )

def challenge_attempt_team(submission, challenge, flags):
    from CTFd.plugins.challenges import ChallengeResponse

    if is_teams_mode():
        user = get_current_user()
        team = get_current_team()
        partials = Partials.query.filter_by(
            team_id=team.id, challenge_id=challenge.id
        ).all()

        submitter_ids = {partial.user_id for partial in partials}

        # Check if the user's submission is correct
        for flag in flags:
            try:
                if get_flag_class(flag.type).compare(flag, submission):
                    submitter_ids.add(user.id)
                    break
            except FlagException as e:
                return ChallengeResponse(
                    status="incorrect",
                    message=str(e),
                )
        else:
            return ChallengeResponse(
                status="incorrect",
                message="Incorrect",
            )

        # The submission is correct so compare if we have received from all team members
        member_ids = {member.id for member in team.members}
        if member_ids == submitter_ids:
            return ChallengeResponse(
                status="correct",
                message="Correct",
            )
        else:
            # We have not received from all members
            return ChallengeResponse(
                status="partial",
                message="Correct but all team members must submit a flag",
            )
    else:
        for flag in flags:
            try:
                if get_flag_class(flag.type).compare(flag, submission):
                    return ChallengeResponse(
                        status="correct",
                        message="Correct",
                    )
            except FlagException as e:
                return ChallengeResponse(
                    status="incorrect",
                    message=str(e),
                )
        return ChallengeResponse(
            status="incorrect",
            message="Incorrect",
        )

