@cache.memoize(timeout=60)
def get_solve_counts_for_challenges(challenge_id=None, admin=False):
    if challenge_id is None:
        challenge_id_filter = ()
    else:
        challenge_id_filter = (Solves.challenge_id == challenge_id,)
    AccountModel = get_model()
    freeze = get_config("freeze")
    if freeze and not admin:
        freeze_cond = Solves.date < unix_time_to_utc(freeze)
    else:
        freeze_cond = true()
    exclude_solves_cond = and_(
        AccountModel.banned == false(),
        AccountModel.hidden == false(),
    )
    solves_q = (
        db.session.query(
            Solves.challenge_id,
            sa_func.count(Solves.challenge_id),
        )
        .join(AccountModel)
        .filter(*challenge_id_filter, freeze_cond, exclude_solves_cond)
        .group_by(Solves.challenge_id)
    )

    solve_counts = {}
    for chal_id, solve_count in solves_q:
        solve_counts[chal_id] = solve_count
    return solve_counts

@cache.memoize(timeout=60)
def get_rating_average_for_challenge_id(challenge_id):
    ratings = Ratings.query.filter_by(challenge_id=challenge_id).all()

    if ratings:
        # Sum upvotes and downvotes
        up = 0
        down = 0
        count = 0
        for rating in ratings:
            count += 1
            if rating.value < 0:
                down += rating.value
            else:
                up += rating.value
        down = abs(down)
        return Rating(up=up, down=down, count=count)
    else:
        return Rating(up=0, down=0, count=0)

