def ctftime():
    """Checks whether it's CTF time or not."""

    start = get_config("start")
    end = get_config("end")

    if start:
        start = int(start)
    else:
        start = 0
    if end:
        end = int(end)
    else:
        end = 0

    if start and end:
        if start < time.time() < end:
            # Within the two time bounds
            return True

    if start < time.time() and end == 0:
        # CTF starts on a date but never ends
        return True

    if start == 0 and time.time() < end:
        # CTF started but ends at a date
        return True

    if start == 0 and end == 0:
        # CTF has no time requirements
        return True

    return False

def ctf_ended():
    if int(get_config("end") or 0):
        return time.time() > int(get_config("end") or 0)
    return False

def unix_time(dt: DateTime) -> int:
    if dt is None or not isinstance(dt, DateTime):
        print("Invalid datetime object for time filter function.")
        return None
    return int((dt - DateTime(1970, 1, 1)).total_seconds())

def unix_time_millis(dt: DateTime) -> int:
    ut = unix_time(dt)
    if ut is None:
        return None
    return ut * 1000

def unix_time_to_utc(t: Union[int, float]) -> DateTime:
    if t is None:
        print("Invalid datetime object for time filter function.")
        return None
    # TODO: The utcfromtimestamp() has been deprecated
    return DateTime.utcfromtimestamp(t)

def isoformat(dt: DateTime) -> str:
    if dt is None or not isinstance(dt, DateTime):
        print("Invalid datetime object for time filter function.")
        return None
    return dt.isoformat() + "Z"

def parse_iso_datetime(value):
    if value in (None, ""):
        return None
    if isinstance(value, DateTime):
        dt = value
    else:
        if isinstance(value, str) and value.endswith("Z"):
            value = value[:-1] + "+00:00"
        dt = DateTime.fromisoformat(value)
    if dt.tzinfo is not None:
        dt = dt.astimezone(timezone.utc).replace(tzinfo=None)
    return dt

def during_ctf_time_only(f):
    """
    Decorator to restrict an endpoint to only be seen during a CTF
    :param f:
    :return:
    """

    @functools.wraps(f)
    def during_ctf_time_only_wrapper(*args, **kwargs):
        if ctftime() or current_user.is_admin():
            return f(*args, **kwargs)
        else:
            if ctf_ended():
                if view_after_ctf():
                    return f(*args, **kwargs)
                else:
                    error = gettext(
                        "%(ctf_name)s has ended", ctf_name=config.ctf_name()
                    )
                    abort(403, description=error)
            if ctf_started() is False:
                if is_teams_mode() and get_current_team() is None:
                    return redirect(url_for("teams.private", next=request.full_path))
                else:
                    error = gettext(
                        "%(ctf_name)s has not started yet", ctf_name=config.ctf_name()
                    )
                    abort(403, description=error)

    return during_ctf_time_only_wrapper

