def log(logger, format, **kwargs):
    logger = logging.getLogger(logger)
    props = {
        "id": session.get("id"),
        "date": time.strftime("%m/%d/%Y %X"),
        "ip": get_ip(),
    }
    props.update(kwargs)
    msg = format.format(**props)
    logger.info(msg)

def create_database():
    url = make_url(app.config["SQLALCHEMY_DATABASE_URI"])
    if url.drivername == "postgres":
        url = url.set(drivername="postgresql")

    if url.drivername.startswith("mysql"):
        url = url.update_query_dict({"charset": "utf8mb4"})

    # Creates database if the database database does not exist
    if not database_exists_util(url):
        if url.drivername.startswith("mysql"):
            create_database_util(url, encoding="utf8mb4")
        else:
            create_database_util(url)
    return url

def drop_database():
    url = make_url(app.config["SQLALCHEMY_DATABASE_URI"])
    if url.drivername == "postgres":
        url = url.set(drivername="postgresql")
    drop_database_util(url)

def generate_account_url(account_id, admin=False):
    if get_config("user_mode") == USERS_MODE:
        if admin:
            return url_for("admin.users_detail", user_id=account_id)
        else:
            return url_for("users.public", user_id=account_id)
    elif get_config("user_mode") == TEAMS_MODE:
        if admin:
            return url_for("admin.teams_detail", team_id=account_id)
        else:
            return url_for("teams.public", team_id=account_id)

def get_model():
    if get_config("user_mode") == USERS_MODE:
        return Users
    elif get_config("user_mode") == TEAMS_MODE:
        return Teams

def get_mode_as_word(plural=False, capitalize=False):
    count = 2 if plural else 1
    if get_config("user_mode") == USERS_MODE:
        word = ngettext("user", "users", count)
    else:
        word = ngettext("team", "teams", count)

    if capitalize:
        word = word.title()
    return word

@cache.memoize(timeout=60)
def get_accessible_module_ids_for_account_id(account_id):
    if account_id is None:
        return set()
    q = (
        Modules.query.with_entities(Modules.id)
        .join(ModuleAudienceAccess, ModuleAudienceAccess.module_id == Modules.id)
        .join(Audiences, Audiences.id == ModuleAudienceAccess.audience_id)
        .join(AudienceMembers, AudienceMembers.audience_id == Audiences.id)
        .filter(AudienceMembers.account_id == account_id)
    )
    return {row.id for row in q.all()}

