def get_configurable_plugins():
    Plugin = namedtuple("Plugin", ["name", "route", "config"])

    plugins_path = os.path.join(app.root_path, "plugins")
    plugin_directories = os.listdir(plugins_path)

    plugins = []

    for dir in plugin_directories:
        if os.path.isfile(os.path.join(plugins_path, dir, "config.json")):
            path = os.path.join(plugins_path, dir, "config.json")
            with open(path) as f:
                plugin_json_data = json.loads(f.read())
                if type(plugin_json_data) is list:
                    for plugin_json in plugin_json_data:
                        p = Plugin(
                            name=plugin_json.get("name"),
                            route=plugin_json.get("route"),
                            config=plugin_json.get("config"),
                        )
                        plugins.append(p)
                else:
                    p = Plugin(
                        name=plugin_json_data.get("name"),
                        route=plugin_json_data.get("route"),
                        config=plugin_json_data.get("config"),
                    )
                    plugins.append(p)
        elif os.path.isfile(os.path.join(plugins_path, dir, "config.html")):
            p = Plugin(name=dir, route="/admin/plugins/{}".format(dir), config=None)
            plugins.append(p)

    return plugins

@cache.memoize(timeout=60)
def get_scoreboard_detail(count, bracket_id=None):
    response = {}

    standings = get_standings(count=count, bracket_id=bracket_id)

    team_ids = [team.account_id for team in standings]

    solves = Solves.query.filter(Solves.account_id.in_(team_ids))
    awards = Awards.query.filter(Awards.account_id.in_(team_ids))

    freeze = get_config("freeze")

    if freeze:
        solves = solves.filter(Solves.date < unix_time_to_utc(freeze))
        awards = awards.filter(Awards.date < unix_time_to_utc(freeze))

    solves = solves.all()
    awards = awards.all()

    # Build a mapping of accounts to their solves and awards
    solves_mapper = defaultdict(list)
    for solve in solves:
        solves_mapper[solve.account_id].append(
            {
                "challenge_id": solve.challenge_id,
                "account_id": solve.account_id,
                "team_id": solve.team_id,
                "user_id": solve.user_id,
                "value": solve.challenge.value,
                "date": isoformat(solve.date),
            }
        )

    for award in awards:
        solves_mapper[award.account_id].append(
            {
                "challenge_id": None,
                "account_id": award.account_id,
                "team_id": award.team_id,
                "user_id": award.user_id,
                "value": award.value,
                "date": isoformat(award.date),
            }
        )

    # Sort all solves by date
    for team_id in solves_mapper:
        solves_mapper[team_id] = sorted(solves_mapper[team_id], key=lambda k: k["date"])

    for i, x in enumerate(standings):
        response[i + 1] = {
            "id": x.account_id,
            "account_url": generate_account_url(account_id=x.account_id),
            "name": x.name,
            "score": int(x.score),
            "bracket_id": x.bracket_id,
            "bracket_name": x.bracket_name,
            "solves": solves_mapper.get(x.account_id, []),
        }

    return response

