def serialize(data, secret=None):
    if secret is None:
        secret = current_app.config["SECRET_KEY"]
    s = URLSafeTimedSerializer(secret)
    return s.dumps(data)

def unserialize(data, secret=None, max_age=432000):
    if secret is None:
        secret = current_app.config["SECRET_KEY"]
    s = URLSafeTimedSerializer(secret)
    return s.loads(data, max_age=max_age)

def sign(data, secret=None):
    if secret is None:
        secret = current_app.config["SECRET_KEY"]
    s = Signer(secret)
    return s.sign(data)

def unsign(data, secret=None):
    if secret is None:
        secret = current_app.config["SECRET_KEY"]
    s = Signer(secret)
    return s.unsign(data)

def hmac(data, secret=None, digest=hashlib.sha1):
    if secret is None:
        secret = current_app.config["SECRET_KEY"]

    if isinstance(data, string_types):
        data = data.encode("utf-8")
    if isinstance(secret, string_types):
        secret = secret.encode("utf-8")

    return _hmac.new(key=secret, msg=data, digestmod=digest).hexdigest()

def __init__(self, initial=None, sid=None, permanent=None):
    def on_update(self):
        self.modified = True

    CallbackDict.__init__(self, initial, on_update)
    self.sid = sid
    if permanent:
        self.permanent = permanent
    self.modified = False

def open_session(self, app, request):
    sid = request.cookies.get(app.session_cookie_name)
    if not sid:
        sid = self._generate_sid()
        return self.session_class(sid=sid, permanent=self.permanent)

    if self.use_signer:
        try:
            sid_as_bytes = unsign(sid)
            sid = sid_as_bytes.decode()
        except BadSignature:
            sid = self._generate_sid()
            return self.session_class(sid=sid, permanent=self.permanent)

    if isinstance(sid, text_type) is False:
        sid = sid.decode("utf-8", "strict")
    val = cache.get(self.key_prefix + sid)
    if val is not None:
        try:
            data = self.serializer.loads(val)
            return self.session_class(data, sid=sid)
        except Exception:
            return self.session_class(sid=sid, permanent=self.permanent)
    return self.session_class(sid=sid, permanent=self.permanent)

